/**
 * **A kept passive bonus is the technology's headline** (batch TT1,
 * `docs/flags.md` item (iiiiiii)).
 *
 * The user: *"unlocking something feels obvious, but the passive bonuses are so
 * easy to miss"*. Most of the bonuses were cut, and the ruling for the ones kept
 * is that each is printed as the technology's headline, in the place an unlock
 * is printed. Three claims hold that here:
 *
 *   1. **Every kept bonus has a headline line**, generated by the describers:
 *      a renewal by `renewalNote`, a node's own rule by `techRuleClauses`. No
 *      prose about a number is written for it.
 *   2. **A node with no kept bonus has no headline**, so the line means
 *      something when it is there.
 *   3. **The node's face prints the headline first**, before its traits, units
 *      and buildings, and counts it in the face's two-line budget. There is no
 *      jsdom in this suite, so this half is read off `renderUnlocks`' source.
 */

import { describe, expect, it } from 'vitest';
import { stripRefs } from '../../src/sim/statecraft';
import { TECH_IDS, type TechId, techDef } from '../../src/sim/techData';
import { techGifts } from '../../src/sim/techUnlocks';
import { renewalNote, techHeadlines } from '../../src/ui/techTree';
import { techRuleClauses } from '../../src/ui/techRuleWords';
import { braceBody, uiSource } from './sourceHelpers';

/** The headline lines of one node, as plain words. */
function said(id: TechId): string[] {
  return techHeadlines(id).map((line) => `${stripRefs(line.name)}${line.note ? ` ${line.note}` : ''}`);
}

describe('a kept bonus is a headline line', () => {
  it('prints the four improvement renewals the ruling keeps', () => {
    expect(said('irrigation')).toEqual(['Farm +1🌾 on fresh water']);
    expect(said('currency')).toEqual(['Plantation +1💰']);
    expect(said('theCataphract')).toEqual(['Pasture +1⚙']);
    expect(said('prospecting')).toEqual(['Mine +1⚙']);
  });

  it('prints the rules the ruling keeps, in the describers’ words', () => {
    expect(said('kingship')).toEqual(['+3 authority capacity']);
    expect(said('stateWorkforce')).toEqual(['newly created workers gain +1 charge']);
    // Batch TT2 moved the second worker charge from Bronze Panoply to The Wheel.
    expect(said('theWheel')).toEqual(['newly created workers gain +1 charge']);
    expect(said('theSilkRoad')).toEqual(['+1 trade route']);
    expect(said('colonialCharters')).toEqual(['new cities are founded with a Town Charter']);
  });

  it('is the generated wording and nothing else', () => {
    for (const id of TECH_IDS) {
      const expected: string[] = [];
      for (const gift of techGifts(id)) {
        if (gift.kind === 'renewal') expected.push(`${gift.name} ${renewalNote(gift)}`);
        if (gift.kind === 'techEffect') expected.push(...techRuleClauses(gift.id).map(stripRefs));
      }
      expect(said(id), id).toEqual(expected);
    }
  });

  it('gives a node whose bonuses were cut no headline at all', () => {
    for (const id of [
      'siegecraft',
      'epicPoetry',
      'theLongCount',
      'artisanry',
      'horology',
      'silkRoad',
      'machinery',
      'feudalism',
      'steel',
      'movableType',
      'theImperialPost',
      // Batch TT2: The Civil Service lost its last bonus when it gained the
      // Courthouse, and Bronze Panoply gave its worker charge to The Wheel.
      'theExaminationHall',
      'bronzePanoply',
    ] as const) {
      expect(techHeadlines(id), id).toEqual([]);
      expect(techDef(id).effects, id).toBeUndefined();
    }
  });
});

describe('the node’s face prints the headline first', () => {
  const face = braceBody(uiSource('techTree.ts'), 'function renderUnlocks(id: TechId): HTMLElement {');

  it('lays the headline lines down before the traits, units and buildings', () => {
    const headline = face.indexOf('techHeadlines(id)');
    expect(headline).toBeGreaterThan(0);
    expect(face.indexOf('techDef(id).traits')).toBeGreaterThan(headline);
    expect(face.indexOf('for (const unit of shownUnits)')).toBeGreaterThan(headline);
    expect(face.indexOf('for (const building of shownBuildings)')).toBeGreaterThan(headline);
  });

  it('spends the face’s budget on the headline and counts what it leaves out', () => {
    expect(face).toContain('headlines.slice(0, FACE_UNLOCKS)');
    expect(face).toContain('FACE_UNLOCKS - shownHeadlines.length - shownTraits.length');
    expect(face).toContain('headlines.length +');
  });

  it('prints a rule’s words through the descriptor, unlinked inside the button', () => {
    expect(face).toContain('setDescriptorText(name, headline.name, { linked: false })');
  });
});
